package main

// Report details quote arbitrary text with Python's repr(): the falsifier's
// output in C-06 and the host's etag in C-07. Go's %q is not repr(), and neither
// is a hand-rolled escaper that only knows about ASCII control characters. These
// tests walk the whole code point space against Python's own printability table
// and check the quoting rules against repr() output recorded by the generator.
//
// Expectations come from testdata/repr_vectors.json, generated by
// testdata/make_repr.py. Regenerate it after a Python upgrade.

import (
	"encoding/json"
	"fmt"
	"os"
	"sort"
	"testing"
	"unicode"
)

type reprVectors struct {
	UnicodeVersion string  `json:"unicode_version"`
	Nonprintable   [][]int `json:"nonprintable"`
	Probes         []struct {
		Input string `json:"input"`
		Repr  string `json:"repr"`
	} `json:"probes"`
}

func loadReprVectors(t *testing.T) reprVectors {
	t.Helper()
	data, err := os.ReadFile("testdata/repr_vectors.json")
	if err != nil {
		t.Fatalf("read repr vectors: %v", err)
	}
	var vectors reprVectors
	if err := json.Unmarshal(data, &vectors); err != nil {
		t.Fatalf("parse repr vectors: %v", err)
	}
	if len(vectors.Nonprintable) == 0 || len(vectors.Probes) == 0 {
		t.Fatal("repr vectors are empty")
	}
	return vectors
}

// printable reads Python's non-printable spans, which are sorted and disjoint.
func (v reprVectors) printable(point rune) bool {
	index := sort.Search(len(v.Nonprintable), func(i int) bool {
		return rune(v.Nonprintable[i][1]) >= point
	})
	if index < len(v.Nonprintable) && point >= rune(v.Nonprintable[index][0]) {
		return false
	}
	return true
}

func TestReprPrintabilityMatchesPythonEverywhere(t *testing.T) {
	vectors := loadReprVectors(t)
	eachRune(func(point rune) {
		if referencePrintable(point) != vectors.printable(point) {
			t.Fatalf("U+%04X: impl2 says printable=%v, Python says printable=%v",
				point, referencePrintable(point), vectors.printable(point))
		}
	})
}

// TestPrintabilityPinsAreExactlyTheDrift keeps the pin table from rotting in
// either direction. It must hold exactly the runes Go prints literally and
// Python escapes, and nothing else; a stale entry would escape a rune Python
// prints, and a missing one would print a rune Python escapes.
func TestPrintabilityPinsAreExactlyTheDrift(t *testing.T) {
	vectors := loadReprVectors(t)
	drift := [][2]rune{}
	reverse := []rune{}
	eachRune(func(point rune) {
		goPrintable := unicode.IsPrint(point)
		pyPrintable := vectors.printable(point)
		if goPrintable && !pyPrintable {
			if n := len(drift); n > 0 && drift[n-1][1] == point-1 {
				drift[n-1][1] = point
			} else {
				drift = append(drift, [2]rune{point, point})
			}
		}
		if pyPrintable && !goPrintable {
			reverse = append(reverse, point)
		}
	})
	if len(reverse) > 0 {
		t.Errorf("Python prints %d rune(s) Go escapes; the pin table only covers one direction: %v",
			len(reverse), reverse[:min(8, len(reverse))])
	}
	if len(drift) != len(referenceUnprintable) {
		t.Fatalf("pin table has %d spans, the measured drift has %d; regenerate with testdata/make_repr.py",
			len(referenceUnprintable), len(drift))
	}
	for i, span := range drift {
		if referenceUnprintable[i] != span {
			t.Fatalf("pin span %d is {0x%04X, 0x%04X}, the measured drift is {0x%04X, 0x%04X}",
				i, referenceUnprintable[i][0], referenceUnprintable[i][1], span[0], span[1])
		}
	}
}

// expectedRuneRepr builds repr() for a single rune from Python's printability,
// independently of the escaper under test.
func expectedRuneRepr(vectors reprVectors, point rune) string {
	quote := "'"
	if point == '\'' {
		quote = `"`
	}
	if vectors.printable(point) && point != '\\' && point != rune(quote[0]) {
		return quote + string(point) + quote
	}
	var escaped string
	switch {
	case point == '\\':
		escaped = `\\`
	case point == '\t':
		escaped = `\t`
	case point == '\n':
		escaped = `\n`
	case point == '\r':
		escaped = `\r`
	case point < 0x100:
		escaped = fmt.Sprintf(`\x%02x`, point)
	case point < 0x10000:
		escaped = fmt.Sprintf(`\u%04x`, point)
	default:
		escaped = fmt.Sprintf(`\U%08x`, point)
	}
	return quote + escaped + quote
}

func TestReprEveryRune(t *testing.T) {
	vectors := loadReprVectors(t)
	eachRune(func(point rune) {
		want := expectedRuneRepr(vectors, point)
		if got := pyStringRepr(string(point)); got != want {
			t.Fatalf("U+%04X: impl2 gives %s, Python gives %s", point, got, want)
		}
	})
}

func TestReprProbes(t *testing.T) {
	vectors := loadReprVectors(t)
	for _, probe := range vectors.Probes {
		if got := pyStringRepr(probe.Input); got != probe.Repr {
			t.Errorf("repr(%q):\n got %s\nwant %s", probe.Input, got, probe.Repr)
		}
	}
}

func TestPyReprScalars(t *testing.T) {
	cases := []struct {
		value any
		want  string
	}{
		{nil, "None"},
		{true, "True"},
		{false, "False"},
		{"it's", `"it's"`},
		{json.Number("4"), "4"},
		{json.Number("1.5"), "1.5"},
	}
	for _, item := range cases {
		if got := pyRepr(item.value); got != item.want {
			t.Errorf("pyRepr(%v) = %s, want %s", item.value, got, item.want)
		}
	}
	if got := pyReprOrNone(""); got != "None" {
		t.Errorf("pyReprOrNone(\"\") = %s, want None", got)
	}
	if got := pyReprOrNone("abc"); got != "'abc'" {
		t.Errorf("pyReprOrNone(\"abc\") = %s, want 'abc'", got)
	}
	if got := pyListRepr([]string{"a", "it's"}); got != `['a', "it's"]` {
		t.Errorf("pyListRepr = %s, want ['a', \"it's\"]", got)
	}
}
